import{_ as p,o as e,c as l,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"《神造物·火种》故事概要","description":"","frontmatter":{},"headers":[],"relativePath":"中层/历史/火种故事.md","filePath":"中层/历史/火种故事.md","lastUpdated":1787065118000}'),i={name:"中层/历史/火种故事.md"};function t(h,a,o,n,d,s){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="《神造物·火种》故事概要" tabindex="-1">《神造物·火种》故事概要 <a class="header-anchor" href="#《神造物·火种》故事概要" aria-label="Permalink to &quot;《神造物·火种》故事概要&quot;">​</a></h1><blockquote><p>《神造物·火种》是聚焦于黑暗时代早期（约黑暗时代 120 年）的故事，上篇讲述毁灭神登神之前，不同种族的普通生灵在压迫中存续、相遇、并点燃第一簇反抗火种的故事；下篇则讲述了一个关于如何面对&quot;代价&quot;的故事。</p></blockquote><h2 id="时代背景" tabindex="-1">时代背景 <a class="header-anchor" href="#时代背景" aria-label="Permalink to &quot;时代背景&quot;">​</a></h2><p>故事发生时，共同体已解体，新五族统治大陆，法师阶级垄断魔法、奴役平民。主角洛尔是黑暗时代的鹿族新生儿，父母在贱民区中早逝或失踪。他不知共同体、不知神明、不知鹿族曾是科研之族，只知道饿、只知道冷、只知道老爷们不能惹。</p><hr><h2 id="《神造物·火种》上篇主线大纲" tabindex="-1">《神造物·火种》上篇主线大纲 <a class="header-anchor" href="#《神造物·火种》上篇主线大纲" aria-label="Permalink to &quot;《神造物·火种》上篇主线大纲&quot;">​</a></h2><hr><h3 id="第一章-觉醒与逃亡" tabindex="-1">第一章：觉醒与逃亡 <a class="header-anchor" href="#第一章-觉醒与逃亡" aria-label="Permalink to &quot;第一章：觉醒与逃亡&quot;">​</a></h3><p>主角：名字叫洛尔，是黑暗时代的鹿族新生儿，男性，年龄约在鹿族成年边缘。父母在贱民区中早逝或失踪，洛尔独自生存。他不知道共同体，不知道神明，不知道鹿族曾是科研之族。他只知道饿，只知道冷，只知道老爷们不能惹。</p><p>核心事件：</p><ol><li>洛尔的魔力第一次失控。起因可能是一次争执、一次饥饿的眩晕，或者只是在贱民区的某个深夜，身体虚弱到临界点时，魔力不受控制地从指尖涌出。</li><li>魔力觉醒意味着死刑。贱民区的某个陌生人——一个为了活下去什么都愿意做的告密者——向老爷们举报了洛尔。</li><li>洛尔被迫逃亡。他没有目的地，只是往远离老爷们的地方跑。</li></ol><p>出口：洛尔独自一人进入荒野，魔力仍在体内不稳定地翻涌，不知道接下来该往哪里走。</p><h3 id="第二章-熊族的枪与星" tabindex="-1">第二章：熊族的枪与星 <a class="header-anchor" href="#第二章-熊族的枪与星" aria-label="Permalink to &quot;第二章：熊族的枪与星&quot;">​</a></h3><p>相遇：洛尔在逃亡途中误入一个废弃的共同体哨站遗址。在这里，他遇到了一个正在寻找什么的熊族潜伏者——米哈伊尔。</p><p>对峙：米哈伊尔发现了洛尔，用枪指着洛尔，并大骂“罪人”，厉声质问：“你难道不知道你们鹿族当年在神殿干了什么吗？罪人！”洛尔完全听不懂。他的困惑是真诚的——他不知道这个熊族在说什么，他甚至不知道什么是“神殿”。米哈伊尔逐渐意识到，这个鹿族不是装傻。他的愤怒落空了。</p><p>相处：因兽潮或其他威胁的逼近，两人被迫合作。危机过后，他们暂时同行。米哈伊尔逐渐意识到昔日比熊族更加辉煌的鹿族，现如今却沦落至此后，态度从敌意转为一种粗粝的、不耐烦的叹息。迫于合作的需求，或者也有几分对洛尔的怜惜，米哈伊尔开始教洛尔一些生存与战斗技巧。在某个夜晚的篝火旁，洛尔发现米哈伊尔擦着一枚褪色的、有红星的徽章。询问后，米哈伊尔说这是之前在遗迹里捡到的共同体徽章。他用漫不经心的语气讲起共同体：电灯、铁路、人民的军队。茫然的洛尔问道“电灯是什么”，米哈伊尔颇感讽刺，发明电灯的种族此刻却连电灯是什么都不知道了。他无奈地笑了笑，说：“没什么，电灯就是电灯。”沉默片刻后，他又补了一句——共同体的神明在那场大灾变后便陷入昏迷，至今未醒。洛尔追问了几句，但米哈伊尔也只是从旧资料里看来的，说不了太细。洛尔没再问，但他记住了“神明”这个词。</p><p>转折：远处出现兽潮的迹象，威胁方向恰好是一片贱民窝棚区。米哈伊尔的第一反应是收拾东西走人——他是潜伏者，任务是第一位的。洛尔争执，认为应该帮助那些人。争执中洛尔撞到米哈伊尔的背包，那枚共同体徽章掉了出来。米哈伊尔弯腰捡起，盯着上面的五角星，静止了几秒。然后骂了一声“妈的”，攥紧徽章，转向兽潮的方向。</p><p>牺牲：米哈伊尔选择引开兽群——不是正面冲锋，而是利用地形制造动静，让兽群偏转方向。他成功了，但他跑得不够快。洛尔站在安全地带，远远地看着米哈伊尔被兽潮淹没。这不是“为保护洛尔而死”，这是为人民而死。在之前，他都刻意无视了那些平民，告诉自己那都是敌人，是共同体覆灭的帮凶。但和洛尔相处之后，他做不到这样欺骗自己了。尽管他本意并不是牺牲——他只是想赌一把，但当他告诉自己“不过就是引走兽潮”的时候，心中其实早已有了答案。临死前，他笑着和哭着的、颤抖的洛尔说他不后悔，并将一个包裹和那枚共同体徽章交给了洛尔，嘱托他完成任务，交给对接人。洛尔痛哭流涕，但最终还是选择了前进。</p><h3 id="第三章-废墟中的狼" tabindex="-1">第三章：废墟中的狼 <a class="header-anchor" href="#第三章-废墟中的狼" aria-label="Permalink to &quot;第三章：废墟中的狼&quot;">​</a></h3><p>相遇：洛尔在这片被米哈伊尔保护的窝棚区里遇到了一只小狼，他的名字叫格雷。格雷比洛尔还小，浑身是伤，一只脚踝有新鲜的枷锁勒痕，看起来刚从奴隶营里逃出来没几天。洛尔看到他的时候，他正蹲在一个受伤的贱民身边，用脏兮兮的布条笨拙地给对方包扎。</p><p>格雷抬头看到洛尔，上下打量了一下，说：“你也受伤了？坐下来，我帮你看看。”</p><p>他完全没意识到自己才是伤势最重的那个。</p><p>相处：格雷是乐天派——身世最惨，但性格最乐观。他饿着肚子会把干粮分给别人，挨了打会说“没事的。”他的善良不是美德，是基因锁让他只能这样。但洛尔不知道基因锁的存在，他只觉得这个狼族傻傻的，但还挺可爱。</p><p>入队：格雷跟着洛尔走，不是因为什么大义，只是因为“你一个人走不安全，我陪你”。洛尔没有拒绝。</p><p>出口：两人结伴同行，洛尔的人生里第一次有了一个需要他保护的人。</p><h3 id="第四章-宴会的血与储藏室的光" tabindex="-1">第四章：宴会的血与储藏室的光 <a class="header-anchor" href="#第四章-宴会的血与储藏室的光" aria-label="Permalink to &quot;第四章：宴会的血与储藏室的光&quot;">​</a></h3><p>被抓：洛尔魔法进一步觉醒，因为一次失控昏迷，其与格雷被一队捕奴队抓获，押送到一个法师老爷的宅邸，成为低等奴隶。</p><p>宴会冲击：洛尔被安排到宴会上端盘子。在大厅里，他看到了新五族法师们聚餐的场景——餐桌上摆着被剖开的智慧生灵的尸体，法师们用手撕着肉，一边吃一边谈笑。洛尔手脚冰凉，魔力几乎失控——他以为桌上的尸体是格雷。一位法师按住了他的肩膀，低声说：“你要干嘛，老实点，回去。”洛尔被推出了宴会厅。那法师的眼神有些不对劲——不是威胁，是像在赶走一只快被碾到的虫子。</p><p>真相：洛尔失魂落魄地回到奴隶棚，却发现格雷还活着。是那位法师以“宠物”的名义把格雷单独调走了。格雷端着一碗粥，看到洛尔回来，笑着说：“你回来啦——我帮厨的给我留了一碗。你吃了吗？”洛尔蹲下来，把脸埋在格雷的肩窝里，很久没有说话。</p><p>摸鱼怪：洛尔开始注意到那位法师不对劲。他让格雷在自己院子里待着，不用干重活；偶尔丢给格雷一包草药，语气很冷淡，但东西是给的；洛尔魔力失控时，他随手压制了回去，动作自然得像在赶苍蝇。某个夜晚，洛尔被安排去打扫内院，误入了一个不该进的门。房间里，那个平日里趾高气昂的法师老爷正面无表情、双眼无神地站在墙角。房间正中的躺椅上，那位之前一直跟在这个法师身边的，作为“宠物”的鹿族青年正以一种极其松弛的姿势瘫在那里，手里端着一杯果汁。门被撞开的巨响让他从躺椅上弹了起来，果汁泼了一身，他的表情是纯粹的、未加修饰的惊吓。然后他手忙脚乱地试图把法师推到角落，又想去藏果汁，最后放弃了，挤出一个比哭还难看的笑容：“额……你……我……我可以解释……”</p><p>指导：这个鹿族青年叫做塞林。他是第一个成功运用精神控制的鹿族，天赋异禀，控制一个法师对他来说几乎没有噪音。但他很胆小，也很怕麻烦——控制法师不是要推翻暴政，只是想过好日子。这也是为什么他后来被洛尔打趣地称之为摸鱼怪。塞林愿意教洛尔魔法，不是因为“同族之情”，而是因为自己的确被洛尔发现了，以及“你那个魔力再乱窜，会把房子炸飞，我的果汁杯就保不住了”。在储藏室的几个夜晚，塞林教会了洛尔如何感知魔力、如何压制、如何引导，以及，塞林刻意强调了，魔法不是什么好东西，能不使用魔法，就不要使用魔法，这是塞林与那群法师长期相处后坚信的结论。</p><p>某次，洛尔问起那晚宴会上法师食人的事。塞林的语气很平淡，像是在陈述一条自然法则：那是顶级法师的必经之路。弱小的法师不必如此，但那些强大的法师无一不是精神扭曲、躯体病态的怪物。只有新鲜的血肉——智慧生物的血肉——才能缓解那具崩坏身体里的诅咒。这是顶层法师间的常识，也是他们的秘密。洛尔想起那晚撕扯血肉的手和谈笑的声音，胃里一阵翻涌。食人是顶级法师最终的病理，但此时的洛尔还远没到那一步。然而，那恐怖的景象还是让他开始“自己吓自己”。 某个深夜，塞林睡熟后，洛尔独自躲在储藏室角落，偷摸的地咬破了自己的手指。他舔舐着自己的鲜血，闭上眼睛感受，试图确认自己是否对“人肉的味道”产生了渴望。血液的铁锈味让他一阵反胃，他长舒一口气，得出结论：“我没有渴望，我还是我。”但他依然心有余悸，在“究竟是真的没事，还是我已经开始异化”的恐慌中反复徘徊。</p><p>危机：塞林控制的法师其实早已被其余法师察觉到了不对劲，一开始他们不以为然，但随着其对洛尔和格雷明显的包庇，这份怀疑愈发浓重，危机即将爆发。与此同时，塞林也在洛尔的影响下逐渐觉醒，不再逃避那些面前哀嚎着的同族。最终，摸鱼怪决定不再摸鱼。面对危机，他主动出击，超载自己，将自己变成了一个转接装置——让其余鹿族奴隶通过他来编织精神控制的网络。他一个人承受了所有人的噪音，将整栋府邸的数个高层一举控制。本都做好牺牲准备的塞林，却忽然发现那些同族奴隶都围了过来，根据之前塞林通过洛尔告诉给他们的方法，开始主动分担控制压力。最终，整栋府邸的全部高层都被塞林与奴隶同族所控制，危机被彻底化解。</p><p>但代价已经埋下。塞林的精神控制网络离不开他这个“转接装置”，他从此再也无法离开法师的地盘。他将自己从一个人，变成了一件工具。他知道这一切，但他没有告诉洛尔。洛尔离开时，他没有挽留，只是摆了摆手，语气和往常一样懒散：“你们继续前进吧。我们的战场在这里。”</p><p>出口：洛尔掌握了基本的魔力控制。塞林与控制着法师的奴隶们留了下来。洛尔带着格雷，在一个塞林安排好的时机离开了宅邸。</p><h3 id="第五章-兔村——避难所的真相" tabindex="-1">第五章：兔村——避难所的真相 <a class="header-anchor" href="#第五章-兔村——避难所的真相" aria-label="Permalink to &quot;第五章：兔村——避难所的真相&quot;">​</a></h3><p>前往兔村：米哈伊尔死前曾告诉洛尔，如果走投无路，可以去南方山林找一个叫兔村的地方。洛尔记得这句话。在与米哈伊尔的对接人碰面、完成了米哈伊尔生前交代的任务之后，洛尔决定带着格雷去找兔村。</p><p>萌芽：在前往兔村的路上，洛尔用魔法轻松解决了几次小麻烦（如驱赶野兽、生火）。他发现自己对魔力的控制越来越得心应手，心中开始悄然滋生一种 “法师化的傲慢”——“魔法也不是那么恐怖，原来魔法不过如此。”同时他也开始更加频繁的使用魔法，甚至在无聊的时候用魔法娱乐。这种傲慢成为他无视早期异化警告的遮羞布。</p><p>相遇：在山林边缘，洛尔遇到了一个兔族青年——斯科克。斯科克是兔村的外围巡逻者，正在偷偷帮助逃亡者。他发现了洛尔和格雷，犹豫之后决定带他们回村。</p><p>兔村面貌：此时的兔村还很小——不是村子，只是一片山林深处的窝棚群，住着几十个逃亡者。这里刚刚建立没多久，还在为过冬的粮食发愁，秩序也还在摸索之中。洛尔注意到村边住着一个白发金瞳的女性，外貌独特，没有毛茸茸的皮肤，独自一人，似乎从不与人交谈。当洛尔第一次在村口用魔法生火，并下意识地用一种俯视的姿态驱赶靠近的野兽时，伊芙琳远远地看了他一眼。那一眼很短，没有赞许，只有一种沉静的审视。斯科克只说那是位精灵族，很早就在这片山林里了，兔村建起来后便跟着住下，从不惹事，但也从不帮忙。见到了几乎只存在于传说中的神秘种族让洛尔甚是惊讶，但也仅是惊讶，毕竟精灵族不问世事已是常识。</p><p>面见长老：斯科克紧张兮兮地安排洛尔住下，反复叮嘱“别让长老知道”。洛尔和格雷小心翼翼地躲了几天，直到某次捕奴队的例行巡逻逼近，斯科克不得不带洛尔去见长老求助。洛尔见到了兔族长老——科伦。科伦长老淡定地听完斯科克结结巴巴的汇报，慢悠悠地说：“那个巡逻队，三天前我就打过招呼了。他们不会进这片林子。”斯科克愣住了。原来长老一直都知道。那些逃亡者的存在、斯科克偷偷送的食物、山外的捕奴队动向——他全都知道，一直在暗中打马虎眼，只是从不公开表态。</p><p>出口：洛尔在兔村暂时安顿下来。斯科克因这次事件，正式成为洛尔的伙伴。</p><h3 id="第六章-捕奴队——点燃火种" tabindex="-1">第六章：捕奴队——点燃火种 <a class="header-anchor" href="#第六章-捕奴队——点燃火种" aria-label="Permalink to &quot;第六章：捕奴队——点燃火种&quot;">​</a></h3><p>威胁逼近：一个新来的流浪者行踪没有隐匿住，触动了一支规模较大的捕奴队向兔村方向逼近。兔村陷入恐慌。这里是流浪者的避难所，大家都是逃亡者，没有人想打仗。科伦长老沉默着，评估局势：转移村子来不及，但抵抗又没有人有经验。此时，逐渐有人的目光转向了那个把捕奴队引过来的新人，他们没有说话，但意思已经很明确了——干脆把他交出去吧。</p><p>洛尔站出来：看着众人眼神中的恐惧，洛尔心中有什么东西终于爆发了。那是质问，是愤怒，是来自保护人民的理想，是决定反抗压迫的火种。于是他站出来说，不能跑。跑了，捕奴队也会发现这里，以后这里永远都会有捕奴队。只有打退他们，让他们觉得这里不值得来，才是真办法。</p><p>组织抵抗：洛尔从塞林那里学会了魔法的控制，有了实战能力。同时，他把米哈伊尔交给他的枪塞给了斯科克，教他如何瞄准。格雷在人群中帮忙——不是战斗，是帮老幼转移，用他的乐天稳定大家的情绪。</p><p>战斗：捕奴队进入了山林。兔族利用地形优势骚扰和分散敌人，洛尔的魔法在关键时刻击伤了带队的法师，米哈伊尔的枪则用来压制那些不会魔法的普通战士。这支捕奴队习惯了面对发抖的奴隶，没有习惯面对有组织的反击。最终，捕奴队溃散，仅剩的法师暴怒扑来。洛尔战胜了法师，流着血，踩在法师的胸膛之上。在这一刻，洛尔心中涌起的不仅是保护家园的愤怒，更有一种属于法师的、俯视众生的傲慢幻觉。他无视了法师的求饶，默默地将武器刺入对方胸膛，一次又一次，嘴角不知什么时候起微微上扬，动作中带着连他自己都没察觉的残忍与冷酷。</p><p>战后：这场战斗不大——只是一队捕奴队——但兔村赢了。人们的眼中多了些什么，那是反抗的火种。这是这里的人们第一次知道：法师不是不可战胜的，老爷们不是不能反抗的。战后，兔村不再是流浪者营地，而是一个有守护者的避难所。洛尔没有离开，他成为了兔村的第一代守护者，在众人的欢呼声中，洛尔站在高处，双眼闪烁着什么，难说是自信，还是自大，而在一次遇见精灵时，精灵那相比之前更加冷漠的眼神让洛尔压抑不住心中的疑惑，他上前询问，精灵没有多说，只是告诉了主角一句“力量终有代价，我等着你。”</p><p>洛尔的变化：战斗之后，洛尔逐渐发现自己的魔力出现了增强。他不觉得有什么奇怪，甚至一时欣喜于力量的增长。他没有注意到，那位精灵族女子在某个清晨从他身边经过时，看了他一眼。那一眼很短，但眼神里不是赞许，也不是担忧，而是一种沉静的审视，像是在确认什么。</p><p>新五族的动向：新五族高层得知一支捕奴队在山林中遭到顽强抵抗后极为震怒，认为兔族给脸不要脸，其中几人主张派出重兵荡平那片区域以儆效尤。但几道声音同时在决策层响起——“那片山林地形复杂，易守难攻”、“主力深入山林的耗费太高，不值得为一群山野逃奴兴师动众”、“目前有更紧要的事需处理”。这些话听起来各有道理，却来自不同的法师口中。其中几位法师说话时眼神平静，语气如常，但共同之处就是他们最近都养了一个鹿族“宠物”。在这片山林之外，塞林正在用他的方式完成当初对洛尔的承诺——不是保护，而是牵制；不是正面对抗，而是让齿轮在最关键的时刻卡在错误的方向。最终，新五族放弃了大规模清剿兔村的计划，任由那片山林维持着脆弱的平静。</p><p>出口：洛尔成为兔村的守护者，扛起了保护这片土地的大梁。斯科克在他身边并肩作战。格雷继续着他的乐天，在村子里帮忙、讲笑话、给新来的逃亡者包扎伤口。塞林的网络在外面继续运转，偶尔会有物资通过鹿族的渠道送到山林边缘。这个故事不以死亡收尾。它以火种的存续收尾。</p><hr><h2 id="《神造物·火种》下篇主线大纲" tabindex="-1">《神造物·火种》下篇主线大纲 <a class="header-anchor" href="#《神造物·火种》下篇主线大纲" aria-label="Permalink to &quot;《神造物·火种》下篇主线大纲&quot;">​</a></h2><hr><h3 id="第七章-颅核与再启程" tabindex="-1">第七章：颅核与再启程 <a class="header-anchor" href="#第七章-颅核与再启程" aria-label="Permalink to &quot;第七章：颅核与再启程&quot;">​</a></h3><p>精灵的那一句话，洛尔记在心里，但的确不明白是什么意思。随着日子一天天过去，洛尔也发生了一些他自己都没有意识到的变化，一开始只是变的有点更“懒”了，更“贪吃”了。同时洛尔也不知为何就生了病，发了烧，而且，本应很快好转的症状却一天比一天差，情况急转直下，随着情况变差的，则是那愈发强大，逐渐超出洛尔预期的魔力，洛尔感觉他现在可以轻易撕碎当初的一整队捕奴队，他感到兴奋，自豪，他甚至开始主动想象那些鲜血淋漓的场面，并开始感叹那些卑微的普通人的弱小，鄙夷精灵族不明不白的劝告，在洛尔没有意识到的点滴之间，他逐渐变的偏执，自负，贪婪，暴虐。同行者们逐渐感到不适，最终，斯科克和洛尔爆发了争执，一旁的格雷试图劝说。但效果甚微，只能干着急，争吵中，洛尔逐渐愤怒，失控，但就在即将用魔法撕碎斯科克的瞬间，格雷瞬间冲了过来，并将自己的手臂主动伸进了洛尔的嘴里，随后猛击洛尔下颚，让洛尔生生咬进了自己的血肉。 鲜血入喉，洛尔大脑瞬间愣住，他本想赶快张开嘴，却下意识的吮吸了一口鲜血，那是他这辈子都没有体验过的美味，这是多么可怕啊，这种恐怖的感觉让洛尔顿时醒悟了过来。看着面前膛目结舌的斯科克，和抱住了自己，流淌着鲜血，却满脸微笑的格雷，洛尔愣住了，他急忙吐出了格雷的手臂，却下意识的舔舐着唇齿间的血液，洛尔无力的瘫倒在了地上，双目无神，什么都没有说。</p><p>没有时间悲伤，清醒的神智每一分每一秒都弥足珍贵，短暂的呆滞过后，理智回归大脑，洛尔顾不上这一切，只是狼狈的奔向了精灵族所住的地方。格雷见状，自然的跟了上去，而斯科克在犹豫过后，则选择了先去向科伦长老汇报情况。 “她知道些什么，她一定有办法，对……” 见到狼狈的洛尔，精灵族似乎早有预料，她拿起一个针筒，给洛尔注射了某种东西，瞬间，洛尔就感觉头脑清醒了不少。 “我——” “那东西治标不治本，你们跟我来。” 洛尔和格雷跟着精灵族前往一处未知的地点，位于兔村不远处的后山之中。路上，精灵族讲述自己的名字，与一些重要的真相，她说她的名字是艾莉芙。她又说，不是魔法导致疾病，而是疾病催生了魔法。身体的崩坏才能换来更强大的法力。不过，只要颅核不损坏，身体的疾病就永远不会彻底失控，普通的食物都被污染了，对没有颅核的人来说都是毒药，只有健康的新鲜血肉才不是。而之所以普通法师不用食人，强大的法师需要，正是因为那些强大的法师，其脑内的颅核已经损毁，彻底的失去了功能，所以疾病才会进一步发展，同时畸形的身体导致大脑思维混乱，更原始，兽性，极端。此时格雷则在一旁询问什么是颅核，艾莉芙顿了一下，随后看向洛尔，但没想到洛尔也一脸迷茫，于是艾莉芙轻轻叹了口气，好似在感叹洛尔和格雷怎么什么都不知道一样，随后解释道颅核是这个世界的智慧生命特有的器官，是一个乒乓球大小的白色类球形硬核，位于下丘脑与脑干中间。 一时间，种种疑惑出现在了天生好奇的洛尔脑中，颅核到底是干什么的？食物被污染是什么意思？普通魔兽的血肉不行吗？难道就是因为魔兽没有颅核？有颅核的魔兽会不会就没有魔力了？为什么智慧生物才有颅核？以及，魔法到底是什么？为什么疾病会催生魔法？面前的精灵族——艾莉芙貌似都有答案。但此时此刻，显然不是探求知识的时候。洛尔需要的，是现在应该怎么做。</p><p>艾莉芙将洛尔与格雷带到了后山的一个山洞中，并打开了一扇秘门： “哦，对了，有人说我居住于你们的兔村。实际上，这里就是我本来的住所。” 通道不算长，洛尔一行人很快来到了一间看起来风格与外界迥异（科技，可理解为近未来风）的，甚是宽广的地下室内。 格雷看着艾莉芙用一堆自己完全没见过也完全不认识的器械给洛尔做了一系列检查，随后，艾莉芙便走到了一旁，开始处理起了数据，并留下了格雷和洛尔两人。此时的格雷伤口还未被包扎，洛尔看到后又是一阵难以言喻的沉默，格雷注意到后，本想默默将手臂藏起来，却被洛尔拽出，并用自己随身携带的医用品。开始细致的为其处理伤口。格雷看着洛尔盯着自己伤口，却不敢抬头与自己对视的双眼，本想说些什么，话到嘴边却什么都没有了，只是静静的望着洛尔，伤口的确还在痛，但格雷的嘴角却露出了淡淡的笑容。</p><p>很快，艾莉芙便处理完了数据，并带来了一个噩耗，洛尔的疾病不是一般的疾病，他的颅核本就有罕见的遗传缺陷，他的魔力觉醒本身就是颅核开始失效的预兆，而现在，他的颅核彻底损毁了。 “所以，颅核到底是什么？”，格雷问道。“是什么能抵抗疾病的器官吗？” “不，比那更重要。”艾莉芙答道，她貌似犹豫了一下是否要告诉格雷这一切，但最终，她还是说了。 “颅核，是一个针对高背景辐射环境生存所设计的，被层层保护的原始基因样板，你可以理解为，它记录了你正常情况下本应是什么的样子。你的身体会照着颅核提供的样子对你的身体进行修复，这就是为什么你们的疾病恢复的毫无后遗症，断肢耗费数年也能复生，而魔兽，和那些法师做不到的根本原因。” “洛卡的这个模板，已经不存在了，那里只剩下了炎症的脓液。这意味着，他的身体彻底失去了修复的方向，只能依靠最原始的免疫系统来进行抵抗。他的身体里现在充满了，额，诅咒。而这个世界上，只有颅核完善的生物，才能做到体内干净不附带诅咒。这就是所谓法师食人的根本原因。” “那套老旧的系统，在这个充满诅咒的地方，根本不够用。” 尽管一开始的那些名词洛尔和格雷没听懂，但后面的东西他们都听懂了。 气氛一时间十分沉重，显而易见，情况十分糟糕。 “……我还有救吗？”洛尔问道，他甚至没有信心去询问自己该怎么做。 “自行恢复是不可能的，至于修复……颅核是你身上最精密的器官，哪怕是我也无法修复。”艾莉芙说道。 ”不过，颅核的体外活性很好，排异反应也因其功能特殊而完全不存在，所以我完全可以为你移植一颗新的颅核，但你知道的，要想移植一颗功能完善的颅核。“ 说到这里，艾莉芙停了下来，但洛尔知道后面是什么。 要想移植一颗功能完善的颅核，就需要一颗功能完善的颅核。</p><p>格雷意识到后当即表示可以使用它的颅核，但这一提案即刻被洛尔否决了，同时，洛尔开始询问真的没有办法了吗。本预期得到绝望恢复的洛尔却在艾莉芙的沉思后得到了新的答复——去找那位建立了共同体的”神明“，唯有神明的伟力可以改变这一切。而这并不是空穴来风，共同体历史中有颅核损毁，却被神明治疗痊愈的明确案例记载，而这也是唯一的案例记载。洛尔疑问道那位神明在当年的灾难后早已陷入昏迷（米哈伊尔在给洛尔科普历史的时候提到过），但艾莉芙知道，那位神明已经醒来了，并且就在旧首都的神殿里，并表示原因不便透露。这条道路充满了艰辛困苦，但无论如何，这是唯一的办法了。 但洛尔依旧绝望，他深知自己的身体状况难以支撑这次漫长旅途，格雷则主动提出由他去帮洛尔求见神明。但被洛尔坚决否定，同时艾莉芙也认为格雷的性格的确更加不可能。</p><p>洛尔的理智告诉他，移植格雷的颅核是唯一的办法，但他不愿意接受这样的办法，他坚信一定还有别的办法，于是一番争执无果后，伊芙琳建议格雷和洛尔（主要是洛尔）回去想一想，药效可以持续四十八小时，等一天再过来也来得及。洛尔一夜无眠，但最终，洛尔还是同意了将格雷的颅核移植给自己的决定，做出这一决定的洛尔失魂落魄，仿佛失去了浑身的力气，在见到格雷时，甚至下意识的扭过头，不愿或者说不敢去面对那个仍旧在微笑的小狼。手术顺利完成，随后，洛尔去求见神明，而格雷则被封入艾莉芙的特殊舱室，进行低代谢冬眠，以保持躯体健康，直到洛尔回来，再由艾莉芙将他的颅核再移植回去，尽管这几乎就等于将自己的命交给了洛尔，但格雷相信洛尔一定能回来。</p><p>临出发前，艾莉芙又交代了格雷几件事情，她说她有一个精灵同胞，叫做伊芙琳，其状态有点“难以形容”，洛尔可以去找她，她或许可以提供一定的帮助，并且艾莉芙表示，如果可以的话，洛尔最好也带着伊芙琳去见一见神明。以及，艾莉芙让洛尔替自己给神明带一句话，让洛尔帮自己问问神明“到底还在忙什么？”</p><h3 id="第八章-酒馆里的精灵" tabindex="-1">第八章：酒馆里的精灵 <a class="header-anchor" href="#第八章-酒馆里的精灵" aria-label="Permalink to &quot;第八章：酒馆里的精灵&quot;">​</a></h3><p>洛尔在一间破酒馆找到伊芙琳。</p><p>她趴在桌上睡觉，白发散乱，手边是木质酒杯。法杖斜靠桌沿——布满划痕的金属杖，不是雕花橡木。她抬起头，眼角有眼眵，脸颊有压痕。她告诉洛尔，她梦到过他。好几次。有一次他带着一只小狼。有一次他头上长着角。有一次他哭了，哭完就走了。她问洛尔是不是真的那个。洛尔不知道她在说什么。</p><p>酒馆里的人在她周围空出一圈。没人靠近。洛尔之前打听她时，被问及的人露出惊讶的表情，劝他别去。法师们尤其避着她。原因后来才知道——她杀过数位强大的法师，以及一些惹到她的人。报复她的人也死了。新五族希望她走，她没在乎。</p><p>她没问洛尔的种族，没问目的，没问艾莉芙。法杖往肩上一搭，示意上路。</p><p>同行后，洛尔逐渐注意到她的魔法与所有其他法师不同。她不能控制物体，不能转化物质，不能将水凝成冰刃或将空气压成风刃。她只能创造。凭空造出一个火源来烧水，却无法直接让水热起来。创造一个土块，却无法把散土聚成块。移动物体依赖创造某种力来间接操作，精度差，偶尔让飞来的酒杯砸到自己脑袋。</p><p>她使用魔法极为随意。日常中处处闪着金色的光，频繁到让人觉得浪费。一次洛尔喝完了水囊中的水。正渴着时，伊芙琳接过他的水囊，金光闪过后，将蓄满了水的水囊还给了他。洛尔疑惑道：“这能喝吗？”。伊芙琳则颇具深意的道：“哦，这将会是你这辈子喝过的最——纯净的水了。”</p><p>新五族注意到她与洛尔同行，决定通过绑架洛尔来威胁她离开。洛尔被一整队人劫走，为首的是数名强大法师。危机发生时，伊芙琳没有预兆地出现了。金色光芒之后，绑匪瞬间扭曲着倒地，七窍流血冒烟，随后眼睛被紫色的火焰由内而外的吞噬，有的头颅甚至在紫色的火焰中砰的一声爆裂开来。洛尔十分震惊，但伊芙琳却对杀戮没有表示。洛尔后来才理解——她分不清这是梦境还是现实。对她来说，可能一睁眼一闭眼，自己还趴在酒馆桌上。</p><p>这次事件后当晚，篝火前，洛尔与伊芙琳有了一次长时间的交谈。</p><p>流传的故事中，精灵族能够掌管梦境。对话中。洛尔得知，精灵族的真实情况是能够进入他人的梦境，并将这些梦境“上传”至世界树。这是他们的能力，也是他们的使命。而世界树本身也会成为精灵族区分梦境与现实的锚点。伊芙琳作为精灵族，在与世界树单向断联后，她与其余精灵族一样，都会陷入到自己的梦境之中，无法确认梦境与现实的区别。绝大多数精灵都疯了，他们反复自杀，试图从梦中醒来。而伊芙琳的应对方式则是不再分辨。因为虽然与世界树断联了，但她发现自己仍然能够“上传”梦境。于是她梦里也当真，现实也当真，上传每一个自己遇到的梦境，即使十传九假，也无所谓，以此继续履行自己的使命。分不清，就不再分清。</p><p>抵达新五族势力边界时，伊芙琳停下。洛尔转达了艾莉芙的话——让他带上伊芙琳，去见神明。但她表示分不分清并不重要，这就是她所需要承担的代价。洛尔不理解，只好就此分别，独自走向旧都。</p><h3 id="第九章-第一个村子" tabindex="-1">第九章：第一个村子 <a class="header-anchor" href="#第九章-第一个村子" aria-label="Permalink to &quot;第九章：第一个村子&quot;">​</a></h3><p>抵达：一处小驿站。兼营马厩和茶铺，旅人来往短暂，没有人记住谁。</p><p>第一次被问：客栈老板登记名字和种族。洛尔在“种族”一栏停了半秒，写下“狼族”。他感觉到右侧鹿角在发痒——不是痛，是松动的前兆。</p><p>一个孩子的提问：村口，一个孩子盯着洛尔看了很久，然后问：“你是什么种族？”洛尔没有回答。孩子被母亲拉走了。母亲回头看了他一眼，眼神里没有恶意，只有不确定。</p><p>离开前的脱落：准备离开村子时，洛尔感觉到右侧鹿角彻底松了。他伸手握住，轻轻一拉。鹿角无声脱落。断口平整，没有血，头顶没有任何再长迹象。</p><p>他把这支角扔进了河里。</p><p>出口：洛尔离开第一个村子。头顶两侧光滑，只剩皮肤。行囊里还有第一支角——那支他留下了。他自己也不知道为什么。</p><h3 id="第十章-镇子" tabindex="-1">第十章：镇子 <a class="header-anchor" href="#第十章-镇子" aria-label="Permalink to &quot;第十章：镇子&quot;">​</a></h3><p>抵达：镇子比驿站大得多。三条街，集市，水车，客栈。人来人往，所有人都可能是下一个问他的人。</p><p>集市上的鹿族：洛尔在集市上帮一个老太太捡散落的果子。身体比大脑先反应——他蹲下、捡起、递过去，动作一气呵成。老太太笑着道谢：“狼族都是好心肠。”他转身就走。走了几步才意识到手在抖——他分不清那个动作是他想做的，还是格雷的颅核替他做的。</p><p>鹿族商人的话：某个摊位前，一个鹿族商人打量他一眼，随口说：“狼族啊。你们狼族倒都是热心肠。”洛尔没有回答。转身离开时，商人嘀咕了一句——“刚才那个，是狼族吧？长得挺像，但总觉得哪里……”</p><p>客栈后院的自我辨认：傍晚，客栈后院。洛尔蹲在水缸前看倒影。毛色变浅了，体型在变化，但眼睛还是他的——至少他觉得还是他的。他试图在心里回答“我是谁”，但答案每次组织到一半就散了。</p><p>一天，在路过一条河流时，洛尔遇到了一个落入水中、正不断挣扎的陌生小女孩。这种情况下，无论是洛尔还是格雷，其本能反应都会是去救。但在出手的瞬间，洛尔脑海中警铃大作——他太害怕变成格雷了，害怕那种不计后果的、纯粹的善良。为了向自己证明“我不是格雷，我不是那种傻白甜”，他硬生生的收回了手，改变了迈开的腿的方向，一步一步，强忍着思绪，远离了现场。女孩在水中挣扎，生死成谜。回到旅馆后，洛尔辗转反侧，他以为自己不会这么在乎，但他想错了，洛尔一夜未眠，备受折磨。 第二天，洛尔起了个大早，假装十分不在意的，刻意装出吃瓜，听八卦的戏谑样子，在沿途的邻里间到处打听女孩的下落。最终得知女孩最终被下游路过的船夫救了，什么事都没有。洛尔顿时大松一口气，下意识想用这个客观结果抹平了自己主观的道德负罪感。但鹿族习惯性的理智思考又让他清醒的意识到：如果没有人救援，自己就真的见死不救杀了一个人。他做不到真正的抹平这份负罪感，做不到真正的自欺欺人。他心不在焉的四处闲逛，却不经意间撞见了昨日河中的那个女孩，洛尔在远处静静的望着那个在阳光下和朋友追逐玩耍的女孩，她笑得很开心，洛尔则站在远处的阴影里，双手交叉在胸前，拇指无意识的内扣，在掌心里摩擦。洛尔不知道怎么面对这个女孩，他不敢想那个女孩当时有没有看到他，有没有看到他见死不救。次日，洛尔便收拾行囊，离开了这里。</p><p>出口：洛尔独自离开镇子。焦虑已经堆到喉咙口，但还没有炸出来。他往下一个驿站走，不知道那里有什么在等他。</p><h3 id="第十一章-第三个驿站" tabindex="-1">第十一章：第三个驿站 <a class="header-anchor" href="#第十一章-第三个驿站" aria-label="Permalink to &quot;第十一章：第三个驿站&quot;">​</a></h3><p>抵达：比第一个村子更小的驿站。石砌矮房，马厩，茶铺。傍晚。</p><p>神经质：洛尔坐在角落喝菜汤，脑子里反复转着念头——下一个问他的会是谁？他该怎么答？如果他又下意识做出“善良”的举动该怎么办？他感觉到自己已经到了某种边缘，任何一个日常提问都可能成为压垮他的最后一根稻草。</p><p>狐族少女出场：驿站门被推开，进来一个狐族少女。耳朵上有旧伤，背着一只塞得鼓鼓的行囊。她点了碗汤，环顾一圈，端着碗径自朝洛尔走来。</p><p>“这里有人吗？”</p><p>“……没有。”</p><p>她坐下来。开始喝汤。“有点咸。”然后她开始讲别的事——抱怨路太荒，说前一个镇子物价离谱，讲她遇到过一个用白颜料把兔子耳朵染白了就敢当精灵卖的骗子。她自己说着说着就笑了，笑起来眼睛弯弯的，那道旧伤也跟着弯起来。</p><p>她从头到尾没有问他是谁。</p><p>庆幸：洛尔后来才意识到——她大概是默认了他是狼族。他长得像，举止也像。她没什么好问的。而他那时候还不知道她这么认为。他只感觉到一种溺水许久终于抓住浮木的庆幸——终于有一个人，不问他是谁。</p><p>同行：第二天清晨，她问他要不要一起走。“这条路前面还有好几天的无人区，两个人比一个人安全。”</p><p>他点头。</p><p>她笑了，耳朵轻轻抖了一下。</p><p>他们上路时，太阳刚升起，影子拉得很长。洛尔深吸一口冷空气。后脑里那颗颅核仍在安静地改写他的身体。</p><p>他不知道的是——她走在他右边，心里正想：这个狼族不爱说话，不过倒挺可靠的。</p><p>出口：两人结伴。引信被压在桌下。读者知道炸弹还在，但狐族少女不知道。洛尔也不知道她不知道。</p><h3 id="第十二章-无人区-简纲" tabindex="-1">第十二章：无人区（简纲） <a class="header-anchor" href="#第十二章-无人区-简纲" aria-label="Permalink to &quot;第十二章：无人区（简纲）&quot;">​</a></h3><p>功能：双人行阶段。狐族少女与洛尔建立默契。格雷化持续加深，基因锁愈发显著。洛尔在“自然表现”中不自觉地印证了狐族少女“他是狼族”的认知。</p><p>关键节点：</p><ol><li>某个拦路事件：路遇欺凌或求助情境。洛尔的第一反应仍是冲上去——但他会在行动后拷问自己：这是我在做，还是格雷在做？这种自我审查，是“沉迷抵抗”的苗头。</li><li>狐族少女的观察：她对洛尔的“善良”表示欣赏，言语中将其归因为“你们狼族就是这样”。洛尔沉默。他无法否认，也无法承认。</li><li>浪漫月夜：一个月夜，篝火旁或星空下，洛尔忽然意识到自己对她的感情，也意识到她可能对自己抱有同样的期待。他试图开口——“其实我不是”——却意识到她从没问过。她一直以为他是狼族。她爱上的，是一个她以为是狼族的人。</li></ol><p>他退缩了。</p><p>出口：两人的关系经过这次沉默的退缩后，依旧继续——但洛尔知道，他压下的东西迟早要炸。</p><h3 id="第十三章-旧都神殿" tabindex="-1">第十三章：旧都神殿 <a class="header-anchor" href="#第十三章-旧都神殿" aria-label="Permalink to &quot;第十三章：旧都神殿&quot;">​</a></h3><p>抵达：旧都废墟深处。狐族少女在神明安排下暂时离开，去处理她自己的事。偌大的神殿只剩洛尔一人。</p><p>神明：神明并非沉睡，而是被困——他在神殿深处对抗某个只有他能压制的威胁，无法离开。他的力量被大量消耗，苏醒后能做的极其有限。</p><p>艾莉芙的质问：洛尔转达了艾莉芙的话——“你为什么还避世不出？”神明给出了答案。那个威胁是共同体覆灭的直接原因，也是他昏迷至今的根源。他仍在应对它。</p><p>颅核的真相：最糟糕的事情发生了，洛尔来晚了，洛尔的身体已完全格雷化。物理上的洛尔不存在了，没有属于自己的基因样本。神明无法复原他。</p><p>但神明手中有一些来自共同体时期的碎片基因数据——来自不同种族，残缺不全。他可以尝试用这些碎片拼出一个全新的颅核。它不属于鹿族，不属于狼族，不属于任何一个已知种族。</p><p>“仅理论可行。你会变成什么样子，没人知道。”</p><p>另一个选项：神明可以复制一份洛尔身上那颗颅核——格雷的颅核。安全，确定，不需要冒险。</p><p>洛尔的回答：他选了前者。不是安全的那条路。不是格雷的路。而是一条从未有人走过的、不被任何种族接纳的路。</p><p>他不能做一辈子的格雷，这不是因为他，而是因为那个真正的格雷，他不能替他而活，更不能顶着他的身躯偷生。而且——他是谁不重要。他做什么，才重要。</p><p>出口：洛尔接受了那颗“四不像”的颅核。他的身体将成为一个从未存在过的形态。他离开了神殿。身后，神明独自留在神殿里，继续对抗那个只有他能扛住的东西。</p><h3 id="尾声" tabindex="-1">尾声 <a class="header-anchor" href="#尾声" aria-label="Permalink to &quot;尾声&quot;">​</a></h3><p>冬眠舱：格雷醒了。颅核在他体内完整地运转。</p><p>“洛尔呢？”</p><p>艾莉芙指了指桌子。桌上放着那枚褪色的红星徽章，下面压着一张纸。</p><p>“格雷：你的颅核还给你了。这枚徽章是米哈伊尔的，现在它是你的。替我保管。我不回兔村了。我现在的样子——你不会认得的。你记得那晚你问我，电灯是什么吗？我没回答，但我现在知道了。电灯就是电灯。”</p><p>格雷放下纸。低头看着手臂上那个愈合的齿痕。还在。只是不再痛了。</p><p>他把徽章攥在手里，走向洞口。外面的山林里，兔村的炊烟正在升起。</p><p>都市怪谈：后来，兔村附近流传起一个传说——山林里有一只怪物，谁也没看清过它长什么样。它有时会在捕奴队逼近时发出声响引开他们，有时会在村口留下柴火和野果。有人说像狼族，但体态不对；有人说像鹿族，但没有角。没有人知道它是什么。</p><p>只有格雷，在某个深夜，看着山洞口一串不属于任何种族的脚印，笑了。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/历史/黑暗时代" class="layer-link" data-layer="表层">黑暗时代</a></li><li><a href="./正传历史">正传历史</a></li><li><a href="./../世界/地脉与魔法">地脉与魔法</a></li><li><a href="./../世界/特殊地点">特殊地点</a></li><li><a href="./../../表层/种族/兔族" class="layer-link" data-layer="表层">兔族</a></li><li><a href="./../../表层/种族/精灵族" class="layer-link" data-layer="表层">精灵族</a></li><li><a href="./../人物/艾莉芙">艾莉芙</a></li><li><a href="./../人物/维斯塔">维斯塔</a></li></ul>',131)])])}const q=p(i,[["render",t]]);export{u as __pageData,q as default};
